{{ config(
            materialized='table',
                post_hook={
                    "sql": "DELETE FROM snitch_db.maplemonk.cogs_snapshot_history WHERE \"DATE\" = CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE; INSERT INTO snitch_db.maplemonk.cogs_snapshot_history ( \"DATE\", category_name, new_cat, qty_available, qty_blocked, qty_not_found, qty_bad_inventory, qty_not_synced, qty_putaway_pending, qty_putback_pending, qty_stock_transfer, available_cogs, blocked_cogs, not_found_cogs, bad_inventory_cogs, not_synced_cogs, putaway_pending_cogs, putback_pending_cogs, stock_transfer_cogs, total_cogs_available_wh, qty_offline_available, qty_jit, offline_available_cogs, available_wh_store_cogs, not_sellable_cogs, jit_cogs, total_cogs ) SELECT CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE as \"DATE\", final_output.* FROM ( WITH warehouse AS ( SELECT \"FACILITY\", UPPER(TRIM(REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\'))) AS sku_group, \"Category Name\", SUM(\"INVENTORY\") AS \"Available\", SUM(\"Inventory Blocked\") AS \"Blocked\", SUM(TRY_TO_NUMBER(\"Not Found\")) AS \"Not Found\", SUM(\"Putaway Pending\") AS \"Putaway Pending\", SUM(\"Putback Pending\") AS \"Putback Pending\", SUM(\"Bad Inventory\") AS \"Bad Inventory\", SUM(\"Inventory Not Synced\") AS \"Not Synced\", SUM(\"Stock In Transfer\") AS \"Stock Transfer\" FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"FACILITY\" IN (\'SAPL_EMIZA\', \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\') AND \"DATE\" = (SELECT MAX(\"DATE\") FROM snitch_db.maplemonk.snitch_final_inventory_wh2) GROUP BY \"FACILITY\", UPPER(TRIM(REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\'))), \"Category Name\" ), offline_inv AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, SUM(inventory) AS available_inv, SUM(jit_qty) AS jit_inv FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), cogs AS ( SELECT UPPER(TRIM(SKUGROUP)) AS sku_group, MAX(cost_price) AS cost_price FROM snitch_db.maplemonk.uc_final_item_master GROUP BY 1 ), sku_category AS ( SELECT DISTINCT sku_group, \"Category Name\" AS category_name FROM warehouse ), wh_rollup AS ( SELECT a.\"Category Name\" AS category_name, SUM(a.\"Available\") AS qty_available, SUM(a.\"Blocked\") AS qty_blocked, SUM(a.\"Not Found\") AS qty_not_found, SUM(a.\"Bad Inventory\") AS qty_bad_inventory, SUM(a.\"Not Synced\") AS qty_not_synced, SUM(a.\"Putaway Pending\") AS qty_putaway_pending, SUM(a.\"Putback Pending\") AS qty_putback_pending, SUM(a.\"Stock Transfer\") AS qty_stock_transfer, SUM(a.\"Available\" * COALESCE(b.cost_price, 0)) AS available_cogs, SUM(a.\"Blocked\" * COALESCE(b.cost_price, 0)) AS blocked_cogs, SUM(a.\"Not Found\" * COALESCE(b.cost_price, 0)) AS not_found_cogs, SUM(a.\"Bad Inventory\" * COALESCE(b.cost_price, 0)) AS bad_inventory_cogs, SUM(a.\"Not Synced\" * COALESCE(b.cost_price, 0)) AS not_synced_cogs, SUM(a.\"Putaway Pending\" * COALESCE(b.cost_price, 0)) AS putaway_pending_cogs, SUM(a.\"Putback Pending\" * COALESCE(b.cost_price, 0)) AS putback_pending_cogs, SUM(a.\"Stock Transfer\" * COALESCE(b.cost_price, 0)) AS stock_transfer_cogs FROM warehouse a LEFT JOIN cogs b ON a.sku_group = b.sku_group GROUP BY a.\"Category Name\" ), offline_rollup AS ( SELECT sc.category_name, SUM(oi.available_inv) AS qty_offline_available, SUM(oi.available_inv * COALESCE(c.cost_price, 0)) AS offline_available_cogs, SUM(oi.jit_inv) AS qty_jit, SUM(oi.jit_inv * COALESCE(c.cost_price, 0)) AS jit_cogs FROM offline_inv oi LEFT JOIN cogs c ON oi.sku_group = c.sku_group LEFT JOIN sku_category sc ON oi.sku_group = sc.sku_group GROUP BY sc.category_name ), pre_calculation AS ( SELECT w.category_name as w_cat, o.category_name as o_cat, COALESCE(w.qty_available, 0) as qty_available, COALESCE(w.qty_blocked, 0) as qty_blocked, COALESCE(w.qty_not_found, 0) as qty_not_found, COALESCE(w.qty_bad_inventory, 0) as qty_bad_inventory, COALESCE(w.qty_not_synced, 0) as qty_not_synced, COALESCE(w.qty_putaway_pending, 0) as qty_putaway_pending, COALESCE(w.qty_putback_pending, 0) as qty_putback_pending, COALESCE(w.qty_stock_transfer, 0) as qty_stock_transfer, COALESCE(w.available_cogs, 0) as available_cogs, COALESCE(w.blocked_cogs, 0) as blocked_cogs, COALESCE(w.not_found_cogs, 0) as not_found_cogs, COALESCE(w.bad_inventory_cogs, 0) as bad_inventory_cogs, COALESCE(w.not_synced_cogs, 0) as not_synced_cogs, COALESCE(w.putaway_pending_cogs, 0) as putaway_pending_cogs, COALESCE(w.putback_pending_cogs, 0) as putback_pending_cogs, COALESCE(w.stock_transfer_cogs, 0) as stock_transfer_cogs, COALESCE(o.qty_offline_available, 0) as qty_offline_available, COALESCE(o.qty_jit, 0) as qty_jit, COALESCE(o.offline_available_cogs, 0) as offline_available_cogs, COALESCE(o.jit_cogs, 0) as jit_cogs, (COALESCE(w.available_cogs, 0) + COALESCE(w.blocked_cogs, 0)) AS \"TOTAL_COGS_Available_WH\", (COALESCE(w.not_found_cogs, 0) + COALESCE(w.bad_inventory_cogs, 0) + COALESCE(w.not_synced_cogs, 0) + COALESCE(w.putaway_pending_cogs, 0) + COALESCE(w.putback_pending_cogs, 0) + COALESCE(w.stock_transfer_cogs, 0) + COALESCE(o.jit_cogs, 0)) AS \"Not_Sellable_COGS\" FROM wh_rollup w FULL OUTER JOIN offline_rollup o ON w.category_name = o.category_name ) SELECT CASE WHEN COALESCE(w_cat, o_cat) IN (\'Sweater\') THEN \'Sweaters\' WHEN COALESCE(w_cat, o_cat) = \'Footwear\' THEN \'Shoes\' WHEN COALESCE(w_cat, o_cat) = \'JOGGERS\' THEN \'Joggers & Trackpants\' WHEN COALESCE(w_cat, o_cat) = \'Jacket\' THEN \'Jackets\' WHEN COALESCE(w_cat, o_cat) = \'Trouser\' THEN \'Trousers\' WHEN COALESCE(w_cat, o_cat) = \'PYJAMAS\' THEN \'Night Suit & Pyjamas\' ELSE COALESCE(w_cat, o_cat) END AS \"Category Name\", CASE WHEN COALESCE(w_cat, o_cat) IN (\'Accessories\', \'Default\', \'Co-Ords\', \'Boxers\', \'Inner Wear\', \'Night Suit & Pyjamas\', \'PYJAMAS\', \'Pyjamas\') THEN \'Others\' WHEN COALESCE(w_cat, o_cat) IN (\'Chinos\', \'Trouser\', \'Trousers\') THEN \'Trousers\' WHEN COALESCE(w_cat, o_cat) IN (\'Trackpants\', \'JOGGERS\', \'Joggers & Trackpants\') THEN \'Joggers & Trackpants\' WHEN COALESCE(w_cat, o_cat) IN (\'Shirt\', \'Shirts\') THEN \'Shirts\' ELSE CASE WHEN COALESCE(w_cat, o_cat) IN (\'Sweater\') THEN \'Sweaters\' WHEN COALESCE(w_cat, o_cat) = \'Footwear\' THEN \'Shoes\' WHEN COALESCE(w_cat, o_cat) = \'Jacket\' THEN \'Jackets\' ELSE COALESCE(w_cat, o_cat) END END AS \"New Cat\", qty_available, qty_blocked, qty_not_found, qty_bad_inventory, qty_not_synced, qty_putaway_pending, qty_putback_pending, qty_stock_transfer, available_cogs, blocked_cogs, not_found_cogs, bad_inventory_cogs, not_synced_cogs, putaway_pending_cogs, putback_pending_cogs, stock_transfer_cogs, \"TOTAL_COGS_Available_WH\", qty_offline_available, qty_jit, offline_available_cogs, (\"TOTAL_COGS_Available_WH\" + offline_available_cogs) AS \"Available - WH + Store\", \"Not_Sellable_COGS\", jit_cogs, ( (\"TOTAL_COGS_Available_WH\" + offline_available_cogs) + \"Not_Sellable_COGS\" ) AS total_cogs FROM pre_calculation ORDER BY total_cogs DESC ) as final_output;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            